int main() {
    std::vector<int> v = {10, 20, 30, 40, 50};
    auto it = v.begin() + 1; // Points to 20

    // 1. Insertion shifts subsequent elements (O(N))
    it = v.insert(it, 15); // 'it' must be reassigned with the return value
    // Old iterator pointing to 20 is now invalid.

    // 2. Erase returns the next valid iterator
    it = v.erase(it); // Erases 15, 'it' now points to 20

    // 3. Reallocation invalidates all
    v.reserve(100); // Assume reallocation occurred
    // print_iter(v, it); // UB if reallocation happened
}
